input.command:
cat > /tmp/get_project_envs.mjs << 'EOF'
// Try Rork toolkit API to get project env vars
const TOOLKIT_URL = process.env.EXPO_PUBLIC_TOOLKIT_URL;
const SECRET_KEY = process.env.EXPO_PUBLIC_RORK_TOOLKIT_SECRET_KEY;
const PROJECT_ID = process.env.EXPO_PUBLIC_PROJECT_ID;

console.log('Toolkit URL:', TOOLKIT_URL);
console.log('Project ID:', PROJECT_ID);
console.log('Secret key present:', !!SECRET_KEY);

// Try various endpoints
const endpoints = [
  `/api/projects/${PROJECT_ID}/envs`,
  `/api/projects/${PROJECT_ID}/environment-variables`,
  `/api/projects/${PROJECT_ID}/secrets`,
  `/api/envs`,
  `/api/environment-variables`,
];

for (const ep of endpoints) {
  try {
    const url = `${TOOLKIT_URL}${ep}`;
    const res = await fetch(url, {
      headers: {
        'Authorization': `Bearer ${SECRET_KEY}`,
        'X-Project-Id': PROJECT_ID,
        'Content-Type': 'application/json'
      }
    });
    console.log(`GET ${ep}: HTTP ${res.status}`);
    if (res.ok) {
      const data = await res.text();
      console.log(`  Response: ${data.slice(0, 500)}`);
    }
  } catch (e) {
    console.log(`GET ${ep}: ERROR ${e.message}`);
  }
}
EOF
bun /tmp/get_project_envs.mjs 2>&1

