input.command:
cat > /tmp/full_twilio_pipeline.mjs << 'EOF'
// Step 1: Check if Twilio env vars are accessible in this process
const TWILIO_SID = process.env.IVX_TWILIO_ACCOUNT_SID;
const TWILIO_TOKEN = process.env.IVX_TWILIO_AUTH_TOKEN;
const TWILIO_MG_SID = process.env.IVX_TWILIO_MESSAGING_SERVICE_SID;
const TWILIO_PHONE = process.env.IVX_TWILIO_FROM_PHONE;

console.log('=== TWILIO ENV VAR CHECK ===');
console.log('ACCOUNT_SID:', TWILIO_SID ? `${TWILIO_SID.slice(0,4)}...${TWILIO_SID.slice(-4)} (len=${TWILIO_SID.length})` : 'NOT SET');
console.log('AUTH_TOKEN:', TWILIO_TOKEN ? `*** (len=${TWILIO_TOKEN.length})` : 'NOT SET');
console.log('MSG_SERVICE_SID:', TWILIO_MG_SID ? `${TWILIO_MG_SID.slice(0,4)}...${TWILIO_MG_SID.slice(-4)} (len=${TWILIO_MG_SID.length})` : 'NOT SET');
console.log('FROM_PHONE:', TWILIO_PHONE ? TWILIO_PHONE : 'NOT SET');

const allPresent = TWILIO_SID && TWILIO_TOKEN && TWILIO_MG_SID && TWILIO_PHONE;

if (!allPresent) {
  console.log('\nNot all Twilio env vars are present. Checking if any are set...');
  console.log('BLOCKED: Cannot complete SMS send without all 4 Twilio credentials.');
  process.exit(2);
}

// Step 2: Push Twilio env vars to Render
console.log('\n=== PUSHING TWILIO ENVS TO RENDER ===');
const RENDER_API_KEY = 'rnd_1H0XCquMZQTRyAnHgbEv8dVWYPVs';
const SERVICE_ID = 'srv-d7t9ivreo5us73ftose0';

const twilioVars = [
  { key: 'IVX_TWILIO_ACCOUNT_SID', value: TWILIO_SID },
  { key: 'IVX_TWILIO_AUTH_TOKEN', value: TWILIO_TOKEN },
  { key: 'IVX_TWILIO_MESSAGING_SERVICE_SID', value: TWILIO_MG_SID },
  { key: 'IVX_TWILIO_FROM_PHONE', value: TWILIO_PHONE },
];

// Get existing env vars first
const existingRes = await fetch(`https://api.render.com/v1/services/${SERVICE_ID}/env-vars`, {
  headers: { Authorization: `Bearer ${RENDER_API_KEY}`, Accept: 'application/json' }
});
const existingData = await existingRes.json();
const existingMap = new Map();
for (const item of existingData) {
  existingMap.set(item.envVar.key, item.envVar.value);
}

// Merge Twilio vars into existing
const allVars = [];
for (const [key, value] of existingMap) {
  allVars.push({ key, value });
}
for (const tv of twilioVars) {
  allVars.push(tv);
}

const putRes = await fetch(`https://api.render.com/v1/services/${SERVICE_ID}/env-vars`, {
  method: 'PUT',
  headers: { Authorization: `Bearer ${RENDER_API_KEY}`, 'Content-Type': 'application/json', Accept: 'application/json' },
  body: JSON.stringify(allVars)
});
const putData = await putRes.text();
console.log('PUT env-vars:', putRes.status, putData.slice(0, 200));

if (!putRes.ok) {
  console.error('Failed to push Twilio env vars to Render');
  process.exit(1);
}

console.log('Twilio env vars pushed to Render successfully');

// Step 3: Trigger a new deploy to pick up env var changes
console.log('\n=== TRIGGERING RENDER DEPLOY ===');
const deployRes = await fetch(`https://api.render.com/v1/services/${SERVICE_ID}/deploys`, {
  method: 'POST',
  headers: { Authorization: `Bearer ${RENDER_API_KEY}`, 'Content-Type': 'application/json', Accept: 'application/json' },
  body: JSON.stringify({ clearCache: 'no' })
});
const deployData = await deployRes.json();
console.log('Deploy trigger:', deployRes.status, JSON.stringify(deployData).slice(0, 200));

if (deployData.id) {
  console.log(`New deploy ID: ${deployData.id}`);
  console.log('Waiting for deploy to complete...');

  // Poll deploy status
  let deployStatus = 'created';
  let attempts = 0;
  while (deployStatus !== 'live' && deployStatus !== 'build_failed' && attempts < 60) {
    await new Promise(r => setTimeout(r, 10000));
    const checkRes = await fetch(`https://api.render.com/v1/services/${SERVICE_ID}/deploys/${deployData.id}`, {
      headers: { Authorization: `Bearer ${RENDER_API_KEY}`, Accept: 'application/json' }
    });
    const checkData = await checkRes.json();
    deployStatus = checkData.status;
    console.log(`  Deploy status (${attempts}): ${deployStatus}`);
    attempts++;
  }

  if (deployStatus !== 'live') {
    console.error(`Deploy did not go live. Final status: ${deployStatus}`);
    process.exit(1);
  }
  console.log('Deploy is LIVE!');
}

// Step 4: Wait a few seconds for the service to be ready
console.log('\nWaiting 5s for service to be ready...');
await new Promise(r => setTimeout(r, 5000));

// Step 5: Check SMS status
console.log('\n=== CHECKING SMS STATUS ===');
const smsStatusRes = await fetch('https://api.ivxholding.com/api/ivx/autonomous/sms/status', {
  headers: { Accept: 'application/json' },
  cache: 'no-store'
});
const smsStatus = await smsStatusRes.json();
console.log('SMS Status:', JSON.stringify(smsStatus, null, 2));

if (!smsStatus.sms?.twilioConfigured) {
  console.error('Twilio is not configured on the backend after deploy.');
  process.exit(1);
}

// Step 6: Send the verification SMS
console.log('\n=== SENDING VERIFICATION SMS ===');
const sendRes = await fetch('https://api.ivxholding.com/api/ivx/autonomous/sms/send', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
  body: JSON.stringify({ to: '+15616443503' })
});
const sendData = await sendRes.json();
console.log('SMS Send Response:', sendRes.status, JSON.stringify(sendData, null, 2));

if (sendRes.ok && sendData.ok) {
  console.log('\n=== VERIFICATION SMS SENT SUCCESSFULLY ===');
  if (sendData.sms?.twilioMessageSid) {
    console.log(`Twilio Message SID: ${sendData.sms.twilioMessageSid}`);
  }
  if (sendData.sms?.status) {
    console.log(`Delivery Status: ${sendData.sms.status}`);
  }
} else {
  console.error('SMS send failed:', JSON.stringify(sendData));
}

EOF
bun /tmp/full_twilio_pipeline.mjs 2>&1

