cat > /tmp/scan_all_envs.mjs << 'SCRIPT'
import { readFileSync, existsSync, readdirSync } from 'node:fs';
import { join } from 'node:path';

// Check all possible env file locations
const envPaths = [
  '/home/user/rork-app/.env',
  '/home/user/rork-app/.env.local',
  '/home/user/rork-app/.env.production',
  '/home/user/rork-app/backend/.env',
  '/home/user/rork-app/backend/.env.local',
  '/home/user/rork-app/backend/.env.production',
  '/home/user/rork-app/expo/.env',
  '/home/user/rork-app/expo/.env.local',
];

for (const p of envPaths) {
  if (existsSync(p)) {
    const content = readFileSync(p, 'utf8');
    const twilioLines = content.split('\n').filter(l => l.toLowerCase().includes('twilio'));
    if (twilioLines.length > 0) {
      console.log(`\n=== ${p} ===`);
      for (const line of twilioLines) {
        // Mask the value but show the key
        const eqIdx = line.indexOf('=');
        if (eqIdx > 0) {
          const key = line.slice(0, eqIdx);
