import { readFileSync } from 'node:fs';

// Method 1: process.env
const keys = ['IVX_TWILIO_ACCOUNT_SID', 'IVX_TWILIO_AUTH_TOKEN', 'IVX_TWILIO_MESSAGING_SERVICE_SID', 'IVX_TWILIO_FROM_PHONE'];
console.log('=== process.env ===');
for (const k of keys) {
  console.log(`${k}: ${process.env[k] ? 'SET' : 'NOT SET'}`);
}

// Method 2: /proc/self/environ
try {
  const environ = readFileSync('/proc/self/environ', 'utf8');
  const entries = environ.split('\0');
  for (const k of keys) {
    const found = entries.find(e => e.startsWith(`${k}=`));
    console.log(`/proc: ${k}: ${found ? 'FOUND' : 'NOT FOUND'}`);
  }
} catch(e) {
  console.log('/proc/self/environ:', e.message);
}

// Method 3: Check ALL env vars for anything starting with IVX_TWILIO
const allKeys = Object.keys(process.env);
const twilioLike = allKeys.filter(k => k.includes('TWILIO') || k.includes('twilio'));
console.log('\nAll TWILIO-like keys:', twilioLike.length ? twilioLike : 'NONE');

// Method 4: Check for any AC/MG prefixed values
const acVals = allKeys.filter(k => {
  const v = process.env[k] || '';
  return (v.startsWith('AC') && v.length === 34) || (v.startsWith('MG') && v.length === 34);
});
console.log('Keys with AC/MG values:', acVals.length ? acVals : 'NONE');

// Method 5: Check for phone number +1 values
