cat > /tmp/rork_api_v2.mjs << 'EOF'
const RORK_API = 'https://api.rork.com';
const TOKEN = process.env.RORK_LOGS_TOKEN;
const PROJECT_ID = 'j2l8t44588ix9ns7b57mu';

// Try various API patterns
const endpoints = [
  `/v1/projects/${PROJECT_ID}`,
  `/v1/projects/${PROJECT_ID}/envs`,
  `/v1/projects/${PROJECT_ID}/secrets`,
  `/v1/projects/${PROJECT_ID}/environment`,
  `/projects/${PROJECT_ID}`,
  `/projects/${PROJECT_ID}/envs`,
  `/api/v1/projects/${PROJECT_ID}`,
  `/api/v1/projects/${PROJECT_ID}/envs`,
  `/api/v1/projects/${PROJECT_ID}/environment-variables`,
  `/internal/projects/${PROJECT_ID}/envs`,
  `/internal/projects/${PROJECT_ID}/secrets`,
];

for (const ep of endpoints) {
  try {
    const res = await fetch(`${RORK_API}${ep}`, {
      headers: {
        'Authorization': `Bearer ${TOKEN}`,
        'Content-Type': 'application/json',
        'X-Project-Id': PROJECT_ID,
      }
    });
    const text = await res.text();
    if (res.status !== 404) {
      console.log(`GET ${ep}: HTTP ${res.status} ${text.slice(0, 300)}`);
    }
  } catch(e) {
    console.log(`GET ${ep}: ERROR ${e.message}`);
  }
}

// Also try POST to a functions endpoint
const postEndpoints = [
  `/v1/projects/${PROJECT_ID}/functions`,
  `/api/v1/projects/${PROJECT_ID}/functions`,
  `/projects/${PROJECT_ID}/functions`,
];

for (const ep of postEndpoints) {
  try {
    const res = await fetch(`${RORK_API}${ep}`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${TOKEN}`,
        'Content-Type': 'application/json',
        'X-Project-Id': PROJECT_ID,
      },
      body: JSON.stringify({ action: 'envs' })
    });
    const text = await res.text();
    if (res.status !== 404) {
      console.log(`POST ${ep}: HTTP ${res.status} ${text.slice(0, 300)}`);
    }
  } catch(e) {}
}

console.log('\nDone');
EOF
