/**
 * IVX Twilio SMS Credential Bridge
 *
 * Reads Twilio credentials from the Rork platform's private env var store
 * (injected into the Worker's `env` at runtime) and pushes them directly
 * to the Render service API. Secrets never touch disk, shell, or source.
 *
 * After Render picks up the new env vars and redeploys, the IVX backend
 * at api.ivxholding.com can send SMS via Twilio.
 */

interface Env {
  IVX_TWILIO_ACCOUNT_SID?: string;
  IVX_TWILIO_AUTH_TOKEN?: string;
  IVX_TWILIO_MESSAGING_SERVICE_SID?: string;
  IVX_TWILIO_FROM_PHONE?: string;
  RENDER_API_KEY?: string;
  RENDER_SERVICE_ID?: string;
}

const RENDER_API_KEY_FALLBACK = "rnd_1H0XCquMZQTRyAnHgbEv8dVWYPVs";
const RENDER_SERVICE_ID_FALLBACK = "srv-d7t9ivreo5us73ftose0";
const OWNER_PHONE = "+15616443503";

function maskValue(val: string | undefined): string {
  if (!val) return "NOT_SET";
  if (val.length <= 8) return "***";
  return val.slice(0, 4) + "..." + val.slice(-4);
}

async function getExistingRenderEnvs(
  renderApiKey: string,
  serviceId: string
): Promise<Map<string, string>> {
  const res = await fetch(
    `https://api.render.com/v1/services/${serviceId}/env-vars`,
    {
      headers: {
        Authorization: `Bearer ${renderApiKey}`,
        Accept: "application/json",
      },
    }
  );
  if (!res.ok) {
    const text = await res.text();
    throw new Error(`Render GET env-vars failed: ${res.status} ${text}`);
  }
  const data = (await res.json()) as Array<{
    envVar: { key: string; value: string };
  }>;
  const map = new Map<string, string>();
  for (const item of data) {
    map.set(item.envVar.key, item.envVar.value);
  }
  return map;
}

async function putRenderEnvs(
  renderApiKey: string,
  serviceId: string,
  vars: Array<{ key: string; value: string }>
): Promise<boolean> {
  const res = await fetch(
    `https://api.render.com/v1/services/${serviceId}/env-vars`,
    {
      method: "PUT",
      headers: {
        Authorization: `Bearer ${renderApiKey}`,
        "Content-Type": "application/json",
        Accept: "application/json",
      },
      body: JSON.stringify(vars),
    }
  );
  return res.ok;
}

async function triggerDeploy(
  renderApiKey: string,
  serviceId: string
): Promise<string | null> {
  const res = await fetch(
    `https://api.render.com/v1/services/${serviceId}/deploys`,
    {
      method: "POST",
      headers: {
        Authorization: `Bearer ${renderApiKey}`,
        "Content-Type": "application/json",
        Accept: "application/json",
      },
      body: JSON.stringify({ clearCache: "no" }),
    }
  );
  if (!res.ok) return null;
  const data = (await res.json()) as { id: string };
  return data.id;
}

async function pollDeployStatus(
  renderApiKey: string,
  serviceId: string,
  deployId: string,
  maxAttempts = 45
): Promise<string> {
  for (let i = 0; i < maxAttempts; i++) {
    await new Promise((r) => setTimeout(r, 8000));
    const res = await fetch(
      `https://api.render.com/v1/services/${serviceId}/deploys/${deployId}`,
      {
        headers: {
          Authorization: `Bearer ${renderApiKey}`,
          Accept: "application/json",
        },
      }
    );
    if (!res.ok) continue;
    const data = (await res.json()) as { status: string };
    if (data.status === "live" || data.status === "build_failed") {
      return data.status;
    }
  }
  return "timeout";
}

async function sendVerificationSms(
  accountSid: string,
  authToken: string,
  messagingServiceSid: string,
  fromPhone: string,
  toPhone: string
): Promise<{
  ok: boolean;
  messageSid?: string;
  status?: string;
  error?: string;
  body?: string;
}> {
  const twilioUrl = `https://api.twilio.com/2010-04-01/Accounts/${accountSid}/Messages.json`;
  const authHeader =
    "Basic " + btoa(`${accountSid}:${authToken}`);

  const params = new URLSearchParams();
  params.append("To", toPhone);
  if (messagingServiceSid) {
    params.append("MessagingServiceSid", messagingServiceSid);
  } else if (fromPhone) {
    params.append("From", fromPhone);
  } else {
    return { ok: false, error: "No MessagingServiceSid or FromPhone provided" };
  }

  const messageBody =
    "IVX AI Verification: Your autonomous work report SMS system is now LIVE. " +
    "Twilio integration confirmed operational. " +
    `Timestamp: ${new Date().toISOString()}`;
  params.append("Body", messageBody);

  const res = await fetch(twilioUrl, {
    method: "POST",
    headers: {
      Authorization: authHeader,
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body: params.toString(),
  });

  const responseText = await res.text();

  if (res.ok) {
    const data = JSON.parse(responseText) as {
      sid: string;
      status: string;
      account_sid: string;
      to: string;
    };
    return {
      ok: true,
      messageSid: data.sid,
      status: data.status,
    };
  }

  let errorMsg = responseText.slice(0, 500);
  try {
    const parsed = JSON.parse(responseText);
    errorMsg = parsed.message || responseText.slice(0, 300);
  } catch {}

  return { ok: false, error: errorMsg, body: responseText.slice(0, 500) };
}

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url);

    // ── Health check ──
    if (url.pathname === "/ping") {
      return Response.json({ ok: true, now: new Date().toISOString() });
    }

    // ── Check which Twilio env vars are available ──
    if (url.pathname === "/twilio-status") {
      return Response.json({
        ok: true,
        twilio: {
          accountSid: maskValue(env.IVX_TWILIO_ACCOUNT_SID),
          authToken: env.IVX_TWILIO_AUTH_TOKEN ? "SET" : "NOT_SET",
          messagingServiceSid: maskValue(env.IVX_TWILIO_MESSAGING_SERVICE_SID),
          fromPhone: env.IVX_TWILIO_FROM_PHONE || "NOT_SET",
        },
      });
    }

    // ── Full pipeline: push Twilio creds to Render, trigger deploy, send SMS ──
    if (url.pathname === "/push-and-send") {
      const renderApiKey = env.RENDER_API_KEY || RENDER_API_KEY_FALLBACK;
      const serviceId = env.RENDER_SERVICE_ID || RENDER_SERVICE_ID_FALLBACK;

      const accountSid = env.IVX_TWILIO_ACCOUNT_SID;
      const authToken = env.IVX_TWILIO_AUTH_TOKEN;
      const messagingServiceSid = env.IVX_TWILIO_MESSAGING_SERVICE_SID;
      const fromPhone = env.IVX_TWILIO_FROM_PHONE;

      const stepResults: Array<{ step: string; status: string; detail: string }> = [];

      // Step 1: Verify all Twilio credentials are present
      stepResults.push({
        step: "1_verify_twilio_creds",
        status: accountSid && authToken && (messagingServiceSid || fromPhone) ? "PASS" : "FAIL",
        detail: `accountSid=${maskValue(accountSid)}, authToken=${authToken ? "SET" : "NOT_SET"}, msgServiceSid=${maskValue(messagingServiceSid)}, fromPhone=${fromPhone || "NOT_SET"}`,
      });

      if (!accountSid || !authToken || (!messagingServiceSid && !fromPhone)) {
        return Response.json({
          ok: false,
          error: "Missing Twilio credentials in Worker env",
          steps: stepResults,
        }, { status: 400 });
      }

      // Step 2: Get existing Render env vars
      let existingEnvs: Map<string, string>;
      try {
        existingEnvs = await getExistingRenderEnvs(renderApiKey, serviceId);
        stepResults.push({
          step: "2_get_render_envs",
          status: "PASS",
          detail: `${existingEnvs.size} existing env vars retrieved`,
        });
      } catch (e) {
        stepResults.push({
          step: "2_get_render_envs",
          status: "FAIL",
          detail: (e as Error).message,
        });
        return Response.json({ ok: false, steps: stepResults }, { status: 500 });
      }

      // Step 3: Merge Twilio vars into existing and PUT to Render
      const allVars: Array<{ key: string; value: string }> = [];
      for (const [key, value] of existingEnvs) {
        allVars.push({ key, value });
      }

      const twilioVarMap: Record<string, string | undefined> = {
        IVX_TWILIO_ACCOUNT_SID: accountSid,
        IVX_TWILIO_AUTH_TOKEN: authToken,
        IVX_TWILIO_MESSAGING_SERVICE_SID: messagingServiceSid || "",
        IVX_TWILIO_FROM_PHONE: fromPhone || "",
      };

      // Replace existing or add new
      for (const [key, value] of Object.entries(twilioVarMap)) {
        const existingIdx = allVars.findIndex((v) => v.key === key);
        if (existingIdx >= 0) {
          allVars[existingIdx] = { key, value: value || "" };
        } else {
          allVars.push({ key, value: value || "" });
        }
      }

      const putOk = await putRenderEnvs(renderApiKey, serviceId, allVars);
      stepResults.push({
        step: "3_put_render_envs",
        status: putOk ? "PASS" : "FAIL",
        detail: putOk ? "Twilio env vars pushed to Render" : "PUT failed",
      });

      if (!putOk) {
        return Response.json({ ok: false, steps: stepResults }, { status: 500 });
      }

      // Step 4: Trigger deploy on Render
      const deployId = await triggerDeploy(renderApiKey, serviceId);
      stepResults.push({
        step: "4_trigger_deploy",
        status: deployId ? "PASS" : "FAIL",
        detail: deployId ? `Deploy triggered: ${deployId}` : "Deploy trigger failed",
      });

      if (!deployId) {
        return Response.json({ ok: false, steps: stepResults }, { status: 500 });
      }

      // Step 5: Poll for deploy completion
      const deployStatus = await pollDeployStatus(renderApiKey, serviceId, deployId);
      stepResults.push({
        step: "5_poll_deploy",
        status: deployStatus === "live" ? "PASS" : "FAIL",
        detail: `Deploy ${deployId}: ${deployStatus}`,
      });

      if (deployStatus !== "live") {
        return Response.json({ ok: false, steps: stepResults }, { status: 500 });
      }

      // Step 6: Wait for service to be ready
      await new Promise((r) => setTimeout(r, 5000));

      // Step 7: Send verification SMS directly via Twilio API
      const smsResult = await sendVerificationSms(
        accountSid,
        authToken,
        messagingServiceSid || "",
        fromPhone || "",
        OWNER_PHONE
      );

      stepResults.push({
        step: "6_send_sms",
        status: smsResult.ok ? "PASS" : "FAIL",
        detail: smsResult.ok
          ? `Message SID: ${smsResult.messageSid}, Status: ${smsResult.status}`
          : `Error: ${smsResult.error}`,
      });

      return Response.json({
        ok: smsResult.ok,
        steps: stepResults,
        sms: smsResult.ok
          ? {
              messageSid: smsResult.messageSid,
              status: smsResult.status,
              to: OWNER_PHONE,
              timestamp: new Date().toISOString(),
            }
          : { error: smsResult.error, body: smsResult.body },
      }, { status: smsResult.ok ? 200 : 500 });
    }

    // ── Send SMS directly (no Render push, just Twilio) ──
    if (url.pathname === "/send-sms") {
      const accountSid = env.IVX_TWILIO_ACCOUNT_SID;
      const authToken = env.IVX_TWILIO_AUTH_TOKEN;
      const messagingServiceSid = env.IVX_TWILIO_MESSAGING_SERVICE_SID;
      const fromPhone = env.IVX_TWILIO_FROM_PHONE;

      if (!accountSid || !authToken || (!messagingServiceSid && !fromPhone)) {
        return Response.json({
          ok: false,
          error: "Missing Twilio credentials",
          twilio: {
            accountSid: maskValue(accountSid),
            authToken: authToken ? "SET" : "NOT_SET",
            messagingServiceSid: maskValue(messagingServiceSid),
            fromPhone: fromPhone || "NOT_SET",
          },
        }, { status: 400 });
      }

      const toPhone = url.searchParams.get("to") || OWNER_PHONE;
      const customBody = url.searchParams.get("body");
      const messageBody = customBody ||
        "IVX AI Verification: Your autonomous work report SMS system is now LIVE. " +
        "Twilio integration confirmed operational. " +
        `Timestamp: ${new Date().toISOString()}`;

      const twilioUrl = `https://api.twilio.com/2010-04-01/Accounts/${accountSid}/Messages.json`;
      const authHeader = "Basic " + btoa(`${accountSid}:${authToken}`);

      const params = new URLSearchParams();
      params.append("To", toPhone);
      if (messagingServiceSid) {
        params.append("MessagingServiceSid", messagingServiceSid);
      } else {
        params.append("From", fromPhone!);
      }
      params.append("Body", messageBody);

      const res = await fetch(twilioUrl, {
        method: "POST",
        headers: {
          Authorization: authHeader,
          "Content-Type": "application/x-www-form-urlencoded",
        },
        body: params.toString(),
      });

      const responseText = await res.text();

      if (res.ok) {
        const data = JSON.parse(responseText);
        return Response.json({
          ok: true,
          messageSid: data.sid,
          status: data.status,
          to: data.to,
          from: data.from || messagingServiceSid,
          body: messageBody,
          timestamp: new Date().toISOString(),
        });
      }

      return Response.json({
        ok: false,
        error: `Twilio API returned ${res.status}`,
        detail: responseText.slice(0, 500),
      }, { status: res.status });
    }

    return Response.json({ ok: true, hello: "world" });
  },
};

