      for (const [key, value] of existingEnvs) {
        allVars.push({ key, value });
      }

      const twilioVarMap: Record<string, string | undefined> = {
        IVX_TWILIO_ACCOUNT_SID: accountSid,
        IVX_TWILIO_AUTH_TOKEN: authToken,
        IVX_TWILIO_MESSAGING_SERVICE_SID: messagingServiceSid || "",
        IVX_TWILIO_FROM_PHONE: fromPhone || "",
      };

      // Replace existing or add new
      for (const [key, value] of Object.entries(twilioVarMap)) {
        const existingIdx = allVars.findIndex((v) => v.key === key);
        if (existingIdx >= 0) {
          allVars[existingIdx] = { key, value: value || "" };
        } else {
          allVars.push({ key, value: value || "" });
        }
      }

      const putOk = await putRenderEnvs(renderApiKey, serviceId, allVars);
      stepResults.push({
        step: "3_put_render_envs",
        status: putOk ? "PASS" : "FAIL",
        detail: putOk ? "Twilio env vars pushed to Render" : "PUT failed",
      });

      if (!putOk) {
        return Response.json({ ok: false, steps: stepResults }, { status: 500 });
      }

      // Step 4: Trigger deploy on Render
      const deployId = await triggerDeploy(renderApiKey, serviceId);
      stepResults.push({
        step: "4_trigger_deploy",
        status: deployId ? "PASS" : "FAIL",
        detail: deployId ? `Deploy triggered: ${deployId}` : "Deploy trigger failed",
      });

      if (!deployId) {
        return Response.json({ ok: false, steps: stepResults }, { status: 500 });
      }

      // Step 5: Poll for deploy completion
      const deployStatus = await pollDeployStatus(renderApiKey, serviceId, deployId);
      stepResults.push({
        step: "5_poll_deploy",
        status: deployStatus === "live" ? "PASS" : "FAIL",
        detail: `Deploy ${deployId}: ${deployStatus}`,
      });

      if (deployStatus !== "live") {
        return Response.json({ ok: false, steps: stepResults }, { status: 500 });
      }

      // Step 6: Wait for service to be ready
      await new Promise((r) => setTimeout(r, 5000));

      // Step 7: Send verification SMS directly via Twilio API
      const smsResult = await sendVerificationSms(
        accountSid,
        authToken,
        messagingServiceSid || "",
        fromPhone || "",
        OWNER_PHONE
      );

      stepResults.push({
        step: "6_send_sms",
        status: smsResult.ok ? "PASS" : "FAIL",
        detail: smsResult.ok
          ? `Message SID: ${smsResult.messageSid}, Status: ${smsResult.status}`
          : `Error: ${smsResult.error}`,
      });

      return Response.json({
        ok: smsResult.ok,
        steps: stepResults,
        sms: smsResult.ok
          ? {
              messageSid: smsResult.messageSid,
              status: smsResult.status,
              to: OWNER_PHONE,
              timestamp: new Date().toISOString(),
            }
          : { error: smsResult.error, body: smsResult.body },
      }, { status: smsResult.ok ? 200 : 500 });
    }

    // ── Send SMS directly (no Render push, just Twilio) ──
    if (url.pathname === "/send-sms") {
      const accountSid = env.IVX_TWILIO_ACCOUNT_SID;
      const authToken = env.IVX_TWILIO_AUTH_TOKEN;
      const messagingServiceSid = env.IVX_TWILIO_MESSAGING_SERVICE_SID;
      const fromPhone = env.IVX_TWILIO_FROM_PHONE;

      if (!accountSid || !authToken || (!messagingServiceSid && !fromPhone)) {
        return Response.json({
          ok: false,
          error: "Missing Twilio credentials",
          twilio: {
            accountSid: maskValue(accountSid),
            authToken: authToken ? "SET" : "NOT_SET",
            messagingServiceSid: maskValue(messagingServiceSid),
            fromPhone: fromPhone || "NOT_SET",
          },
        }, { status: 400 });
      }

      const toPhone = url.searchParams.get("to") || OWNER_PHONE;
      const customBody = url.searchParams.get("body");
      const messageBody = customBody ||
        "IVX AI Verification: Your autonomous work report SMS system is now LIVE. " +
        "Twilio integration confirmed operational. " +
        `Timestamp: ${new Date().toISOString()}`;

      const twilioUrl = `https://api.twilio.com/2010-04-01/Accounts/${accountSid}/Messages.json`;
      const authHeader = "Basic " + btoa(`${accountSid}:${authToken}`);

      const params = new URLSearchParams();
      params.append("To", toPhone);
      if (messagingServiceSid) {
        params.append("MessagingServiceSid", messagingServiceSid);
      } else {
        params.append("From", fromPhone!);
      }
      params.append("Body", messageBody);

      const res = await fetch(twilioUrl, {
        method: "POST",
        headers: {
          Authorization: authHeader,
          "Content-Type": "application/x-www-form-urlencoded",
        },
        body: params.toString(),
      });

      const responseText = await res.text();

      if (res.ok) {
        const data = JSON.parse(responseText);
        return Response.json({
          ok: true,
          messageSid: data.sid,
          status: data.status,
          to: data.to,
          from: data.from || messagingServiceSid,
          body: messageBody,
          timestamp: new Date().toISOString(),
        });
      }

      return Response.json({
        ok: false,
        error: `Twilio API returned ${res.status}`,
        detail: responseText.slice(0, 500),
      }, { status: res.status });
    }

    return Response.json({ ok: true, hello: "world" });
  },
};
