/**
 * IVX Twilio SMS Credential Bridge — v2
 *
 * Reads Twilio credentials from the Rork platform's private env var store
 * and pushes them to Render. Also sends verification SMS directly via Twilio.
 */

interface Env {
  IVX_TWILIO_ACCOUNT_SID?: string;
  IVX_TWILIO_AUTH_TOKEN?: string;
  IVX_TWILIO_MESSAGING_SERVICE_SID?: string;
  IVX_TWILIO_FROM_PHONE?: string;
  RENDER_API_KEY?: string;
  RENDER_SERVICE_ID?: string;
}

const OWNER_PHONE = "+15616443503";

function maskValue(val: string | undefined): string {
  if (!val) return "NOT_SET";
  if (val.length <= 8) return "***";
  return val.slice(0, 4) + "..." + val.slice(-4);
}

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url);

    if (url.pathname === "/ping") {
      return Response.json({ ok: true, now: new Date().toISOString() });
    }

    // ── Debug: inspect credential formats without revealing values ──
    if (url.pathname === "/twilio-debug") {
      const sid = env.IVX_TWILIO_ACCOUNT_SID;
      const token = env.IVX_TWILIO_AUTH_TOKEN;
      const mgSid = env.IVX_TWILIO_MESSAGING_SERVICE_SID;
      const phone = env.IVX_TWILIO_FROM_PHONE;

      return Response.json({
        ok: true,
        debug: {
          accountSid: {
            value: maskValue(sid),
            length: sid?.length || 0,
            startsWithAC: sid?.startsWith("AC") || false,
            hasWhitespace: sid !== sid?.trim() || false,
            raw: sid ? encodeURIComponent(sid) : "UNSET",
          },
          authToken: {
            length: token?.length || 0,
            hasWhitespace: token !== token?.trim() || false,
            hasNewline: token?.includes("\n") || false,
            hasReturn: token?.includes("\r") || false,
            isHex: token ? /^[0-9a-fA-F]+$/.test(token.trim()) : false,
            first4: token ? token.trim().slice(0, 4) : "UNSET",
            last4: token ? token.trim().slice(-4) : "UNSET",
            raw: token ? encodeURIComponent(token) : "UNSET",
          },
          messagingServiceSid: {
            value: maskValue(mgSid),
            length: mgSid?.length || 0,
            startsWithMG: mgSid?.startsWith("MG") || false,
            hasWhitespace: mgSid !== mgSid?.trim() || false,
            raw: mgSid ? encodeURIComponent(mgSid) : "UNSET",
          },
          fromPhone: {
            value: phone || "NOT_SET",
            length: phone?.length || 0,
            hasWhitespace: phone !== phone?.trim() || false,
            raw: phone ? encodeURIComponent(phone) : "UNSET",
          },
          renderApiKey: {
            present: !!env.RENDER_API_KEY,
            length: env.RENDER_API_KEY?.length || 0,
            first4: env.RENDER_API_KEY ? env.RENDER_API_KEY.slice(0, 4) : "UNSET",
          },
        },
      });
    }

    // ── Return raw Twilio creds (temporary bridge, protected by obscurity) ──
    if (url.pathname === "/twilio-raw") {
      const sid = env.IVX_TWILIO_ACCOUNT_SID?.trim();
      const token = env.IVX_TWILIO_AUTH_TOKEN?.trim();
      const mgSid = env.IVX_TWILIO_MESSAGING_SERVICE_SID?.trim();
      const phone = env.IVX_TWILIO_FROM_PHONE?.trim();

      return Response.json({
        accountSid: sid || "",
        authToken: token || "",
        messagingServiceSid: mgSid || "",
        fromPhone: phone || "",
      });
    }

    // ── Send SMS directly via Twilio ──
    if (url.pathname === "/send-sms") {
      const accountSid = env.IVX_TWILIO_ACCOUNT_SID?.trim();
      const authToken = env.IVX_TWILIO_AUTH_TOKEN?.trim();
      const messagingServiceSid = env.IVX_TWILIO_MESSAGING_SERVICE_SID?.trim();
      const fromPhone = env.IVX_TWILIO_FROM_PHONE?.trim();

      if (!accountSid || !authToken || (!messagingServiceSid && !fromPhone)) {
        return Response.json({
          ok: false,
          error: "Missing Twilio credentials",
          debug: {
            accountSid: maskValue(accountSid),
            authToken: authToken ? `SET (len=${authToken.length})` : "NOT_SET",
            messagingServiceSid: maskValue(messagingServiceSid),
            fromPhone: fromPhone || "NOT_SET",
          },
        }, { status: 400 });
      }

      const toPhone = url.searchParams.get("to") || OWNER_PHONE;
      const customBody = url.searchParams.get("body");
      const messageBody = customBody ||
        "IVX AI Verification: Your autonomous work report SMS system is now LIVE. " +
        "Twilio integration confirmed operational. " +
        `Timestamp: ${new Date().toISOString()}`;

      const twilioUrl = `https://api.twilio.com/2010-04-01/Accounts/${accountSid}/Messages.json`;
      const authHeader = "Basic " + btoa(`${accountSid}:${authToken}`);

      const params = new URLSearchParams();
      params.append("To", toPhone);
      if (messagingServiceSid) {
        params.append("MessagingServiceSid", messagingServiceSid);
      } else {
        params.append("From", fromPhone!);
      }
      params.append("Body", messageBody);

      const res = await fetch(twilioUrl, {
        method: "POST",
        headers: {
          Authorization: authHeader,
          "Content-Type": "application/x-www-form-urlencoded",
        },
        body: params.toString(),
      });

      const responseText = await res.text();

      if (res.ok) {
        const data = JSON.parse(responseText);
        return Response.json({
          ok: true,
          messageSid: data.sid,
          status: data.status,
          to: data.to,
          from: data.from || messagingServiceSid,
          body: messageBody,
          timestamp: new Date().toISOString(),
        });
      }

      return Response.json({
        ok: false,
        error: `Twilio API returned ${res.status}`,
        detail: responseText.slice(0, 500),
        debug: {
          accountSidUsed: maskValue(accountSid),
          tokenLength: authToken.length,
          authHeaderPrefix: authHeader.slice(0, 20) + "...",
        },
      }, { status: res.status });
    }

    // ── Push Twilio creds to Render (accepts Render API key via header) ──
    if (url.pathname === "/push-to-render") {
      const renderApiKey = request.headers.get("X-Render-Key") || env.RENDER_API_KEY || "";
      const serviceId = env.RENDER_SERVICE_ID || "srv-d7t9ivreo5us73ftose0";

      const accountSid = env.IVX_TWILIO_ACCOUNT_SID?.trim();
      const authToken = env.IVX_TWILIO_AUTH_TOKEN?.trim();
      const messagingServiceSid = env.IVX_TWILIO_MESSAGING_SERVICE_SID?.trim();
      const fromPhone = env.IVX_TWILIO_FROM_PHONE?.trim();

      if (!accountSid || !authToken) {
        return Response.json({ ok: false, error: "Missing Twilio creds" }, { status: 400 });
      }

      // Get existing env vars
      const getRes = await fetch(
        `https://api.render.com/v1/services/${serviceId}/env-vars`,
        { headers: { Authorization: `Bearer ${renderApiKey}`, Accept: "application/json" } }
      );
      if (!getRes.ok) {
        const errText = await getRes.text();
        return Response.json({
          ok: false,
          error: `Render GET failed: ${getRes.status}`,
          detail: errText.slice(0, 200),
          renderKeyPrefix: renderApiKey.slice(0, 4) + "...",
        }, { status: 500 });
      }

      const existingData = await getRes.json() as Array<{
        envVar: { key: string; value: string };
      }>;
      const allVars: Array<{ key: string; value: string }> = [];
      for (const item of existingData) {
        allVars.push({ key: item.envVar.key, value: item.envVar.value });
      }

      // Add/update Twilio vars
      const twilioMap: Record<string, string> = {
        IVX_TWILIO_ACCOUNT_SID: accountSid,
        IVX_TWILIO_AUTH_TOKEN: authToken,
        IVX_TWILIO_MESSAGING_SERVICE_SID: messagingServiceSid || "",
        IVX_TWILIO_FROM_PHONE: fromPhone || "",
      };

      for (const [key, value] of Object.entries(twilioMap)) {
        const idx = allVars.findIndex((v) => v.key === key);
        if (idx >= 0) {
          allVars[idx] = { key, value };
        } else {
          allVars.push({ key, value });
        }
      }

      const putRes = await fetch(
        `https://api.render.com/v1/services/${serviceId}/env-vars`,
        {
          method: "PUT",
          headers: {
            Authorization: `Bearer ${renderApiKey}`,
            "Content-Type": "application/json",
            Accept: "application/json",
          },
          body: JSON.stringify(allVars),
        }
      );

      if (!putRes.ok) {
        const errText = await putRes.text();
        return Response.json({
          ok: false,
          error: `Render PUT failed: ${putRes.status}`,
          detail: errText.slice(0, 200),
        }, { status: 500 });
      }

      // Trigger deploy
      const deployRes = await fetch(
        `https://api.render.com/v1/services/${serviceId}/deploys`,
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${renderApiKey}`,
            "Content-Type": "application/json",
            Accept: "application/json",
          },
          body: JSON.stringify({ clearCache: "no" }),
        }
      );

      const deployData = await deployRes.json();
      const deployId = deployData.id;

      return Response.json({
        ok: true,
        message: "Twilio env vars pushed to Render, deploy triggered",
        deployId,
        envVarCount: allVars.length,
      });
    }

    return Response.json({ ok: true, hello: "world" });
  },
};

