      const messagingServiceSid = env.IVX_TWILIO_MESSAGING_SERVICE_SID?.trim();
      const fromPhone = env.IVX_TWILIO_FROM_PHONE?.trim();

      if (!accountSid || !authToken) {
        return Response.json({ ok: false, error: "Missing Twilio creds" }, { status: 400 });
      }

      // Get existing env vars
      const getRes = await fetch(
        `https://api.render.com/v1/services/${serviceId}/env-vars`,
        { headers: { Authorization: `Bearer ${renderApiKey}`, Accept: "application/json" } }
      );
      if (!getRes.ok) {
        const errText = await getRes.text();
        return Response.json({
          ok: false,
          error: `Render GET failed: ${getRes.status}`,
          detail: errText.slice(0, 200),
          renderKeyPrefix: renderApiKey.slice(0, 4) + "...",
        }, { status: 500 });
      }

      const existingData = await getRes.json() as Array<{
        envVar: { key: string; value: string };
      }>;
      const allVars: Array<{ key: string; value: string }> = [];
      for (const item of existingData) {
        allVars.push({ key: item.envVar.key, value: item.envVar.value });
      }

      // Add/update Twilio vars
      const twilioMap: Record<string, string> = {
        IVX_TWILIO_ACCOUNT_SID: accountSid,
        IVX_TWILIO_AUTH_TOKEN: authToken,
        IVX_TWILIO_MESSAGING_SERVICE_SID: messagingServiceSid || "",
        IVX_TWILIO_FROM_PHONE: fromPhone || "",
      };

      for (const [key, value] of Object.entries(twilioMap)) {
        const idx = allVars.findIndex((v) => v.key === key);
        if (idx >= 0) {
          allVars[idx] = { key, value };
        } else {
          allVars.push({ key, value });
        }
      }

      const putRes = await fetch(
        `https://api.render.com/v1/services/${serviceId}/env-vars`,
        {
          method: "PUT",
          headers: {
            Authorization: `Bearer ${renderApiKey}`,
            "Content-Type": "application/json",
            Accept: "application/json",
          },
          body: JSON.stringify(allVars),
        }
      );

      if (!putRes.ok) {
        const errText = await putRes.text();
        return Response.json({
          ok: false,
          error: `Render PUT failed: ${putRes.status}`,
          detail: errText.slice(0, 200),
        }, { status: 500 });
      }

      // Trigger deploy
      const deployRes = await fetch(
        `https://api.render.com/v1/services/${serviceId}/deploys`,
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${renderApiKey}`,
            "Content-Type": "application/json",
            Accept: "application/json",
          },
          body: JSON.stringify({ clearCache: "no" }),
        }
      );

      const deployData = await deployRes.json();
      const deployId = deployData.id;

      return Response.json({
        ok: true,
        message: "Twilio env vars pushed to Render, deploy triggered",
        deployId,
        envVarCount: allVars.length,
      });
    }

    return Response.json({ ok: true, hello: "world" });
  },
};
