console.log('\n--- Testing Twilio SMS send ---');
const twilioUrl = `https://api.twilio.com/2010-04-01/Accounts/${raw.accountSid}/Messages.json`;
const authHeader = 'Basic ' + Buffer.from(`${raw.accountSid}:${raw.authToken}`).toString('base64');

const params = new URLSearchParams();
params.append('To', '+15616443503');
if (raw.messagingServiceSid) {
  params.append('MessagingServiceSid', raw.messagingServiceSid);
} else {
  params.append('From', raw.fromPhone);
}
params.append('Body', `IVX AI Verification: Autonomous work report SMS system is LIVE. Twilio integration confirmed. Timestamp: ${new Date().toISOString()}`);

const smsRes = await fetch(twilioUrl, {
  method: 'POST',
  headers: { Authorization: authHeader, 'Content-Type': 'application/x-www-form-urlencoded' },
  body: params.toString()
});
const smsText = await smsRes.text();

if (smsRes.ok) {
  const smsData = JSON.parse(smsText);
  console.log('SMS SENT SUCCESSFULLY!');
  console.log(`  Message SID: ${smsData.sid}`);
  console.log(`  Status: ${smsData.status}`);
  console.log(`  To: ${smsData.to}`);
  console.log(`  From: ${smsData.from || smsData.messaging_service_sid}`);
} else {
  console.log(`SMS send FAILED: HTTP ${smsRes.status}`);
  try {
    const errData = JSON.parse(smsText);
    console.log(`  Error code: ${errData.code}`);
    console.log(`  Error message: ${errData.message}`);
    console.log(`  More info: ${errData.more_info}`);
  } catch {
    console.log(`  Raw: ${smsText.slice(0, 300)}`);
  }
}
EOF
