const RENDER_API_KEY = 'rnd_1H0XCquMZQTRyAnHgbEv8dVWYPVs';
const SERVICE_ID = 'srv-d7t9ivreo5us73ftose0';

// 1. Verify Twilio env vars are now on Render
const envRes = await fetch(`https://api.render.com/v1/services/${SERVICE_ID}/env-vars`, {
  headers: { Authorization: `Bearer ${RENDER_API_KEY}`, Accept: 'application/json' }
});
const envData = await envRes.json();
const twilioVars = envData.filter(v => v.envVar.key.includes('TWILIO'));
console.log('=== RENDER TWILIO ENV VARS ===');
for (const v of twilioVars) {
  const val = v.envVar.value;
  const masked = val.length > 8 ? val.slice(0,4) + '...' + val.slice(-4) : val;
  console.log(`  ${v.envVar.key}: ${masked} (len=${val.length})`);
}

// 2. Trigger deploy with correct clearCache value
console.log('\n=== TRIGGERING DEPLOY ===');
const deployRes = await fetch(`https://api.render.com/v1/services/${SERVICE_ID}/deploys`, {
  method: 'POST',
  headers: { Authorization: `Bearer ${RENDER_API_KEY}`, 'Content-Type': 'application/json', Accept: 'application/json' },
  body: JSON.stringify({ clearCache: 'do_not_clear' })
});
const deployData = await deployRes.json();
console.log('Deploy response:', deployRes.status, JSON.stringify({ id: deployData.id, status: deployData.status, message: deployData.message }));

if (deployData.id) {
  console.log(`Deploy ID: ${deployData.id}`);
  console.log('Polling deploy status (max ~6 min)...');

  let status = 'created';
  let attempts = 0;
  while (status !== 'live' && status !== 'build_failed' && attempts < 45) {
    await new Promise(r => setTimeout(r, 8000));
    const checkRes = await fetch(`https://api.render.com/v1/services/${SERVICE_ID}/deploys/${deployData.id}`, {
      headers: { Authorization: `Bearer ${RENDER_API_KEY}`, Accept: 'application/json' }
    });
    const checkData = await checkRes.json();
    status = checkData.status;
    attempts++;
    if (attempts % 5 === 0 || status === 'live' || status === 'build_failed') {
      console.log(`  [${attempts}] status=${status} finishedAt=${checkData.finishedAt || 'pending'}`);
    }
  }

  if (status === 'live') {
    console.log('Deploy is LIVE!');
  } else {
    console.log(`Deploy final status: ${status}`);
  }
}

// 3. Check health endpoint
console.log('\n=== HEALTH CHECK ===');
await new Promise(r => setTimeout(r, 3000));
const healthRes = await fetch('https://api.ivxholding.com/health', { cache: 'no-store' });
const health = await healthRes.json();
console.log('Commit:', health.commit?.slice(0,12));
console.log('Database:', health.databaseConfigured);
console.log('AI OK:', health.ai?.ok);
console.log('Boot time:', health.bootTime);

// 4. Check SMS status on backend
console.log('\n=== SMS STATUS ===');
const smsRes = await fetch('https://api.ivxholding.com/api/ivx/autonomous/sms/status', { cache: 'no-store' });
const sms = await smsRes.json();
console.log('Twilio configured:', sms.sms?.twilioConfigured);
console.log('Phone configured:', sms.sms?.phoneConfigured);
console.log('Phone masked:', sms.sms?.phoneMasked);
console.log('Scheduler running:', sms.sms?.schedulerRunning);

EOF
