/**
 * IVX Full Credential Bridge — v3
 *
 * Exposes ALL private env vars from the Rork platform so they can be
 * bridged to Render. Also sends verification SMS via Twilio.
 */

interface Env {
  IVX_TWILIO_ACCOUNT_SID?: string;
  IVX_TWILIO_AUTH_TOKEN?: string;
  IVX_TWILIO_MESSAGING_SERVICE_SID?: string;
  IVX_TWILIO_FROM_PHONE?: string;
  EXPO_PUBLIC_SUPABASE_URL?: string;
  SUPABASE_URL?: string;
  IVX_SUPABASE_URL?: string;
  SUPABASE_SERVICE_ROLE_KEY?: string;
  SUPABASE_SERVICE_KEY?: string;
  EXPO_PUBLIC_SUPABASE_ANON_KEY?: string;
  SUPABASE_ANON_KEY?: string;
  SUPABASE_DB_URL?: string;
  DATABASE_URL?: string;
  AI_GATEWAY_API_KEY?: string;
  IVX_AI_GATEWAY_KEY?: string;
  JWT_SECRET?: string;
  APP_SECRET?: string;
  AWS_ACCESS_KEY_ID?: string;
  AWS_SECRET_ACCESS_KEY?: string;
  AWS_REGION?: string;
  CLOUDFRONT_DISTRIBUTION_ID?: string;
  IVX_RENDER_API_KEY?: string;
  RENDER_API_KEY?: string;
  RENDER_SERVICE_ID?: string;
  GITHUB_TOKEN?: string;
  GITHUB_REPO_URL?: string;
  IVX_OWNER_EMAIL?: string;
  IVX_OWNER_PASSWORD?: string;
  IVX_OWNER_TOKEN?: string;
  IVX_OWNER_TOKEN_SESSION?: string;
  IVX_OWNER_SUPABASE_ACCESS_TOKEN?: string;
  IVX_AI_SYSTEM_SECRET?: string;
  IVX_INTERNAL_DEPLOY_SECRET?: string;
  IVX_INTERNAL_WORKER_ID?: string;
  IVX_OWNER_VARIABLES_ENCRYPTION_KEY?: string;
  IVX_OWNER_REGISTRATION_EMAILS?: string;
  IVX_SES_FROM_EMAIL?: string;
  IVX_TWILIO_ACCOUNT_SID?: string;
  [key: string]: string | undefined;
}

const OWNER_PHONE = "+15616443503";

function mask(val: string | undefined): string {
  if (!val) return "NOT_SET";
  if (val.length <= 8) return "***";
  return val.slice(0, 4) + "..." + val.slice(-4);
}

// All env var keys we want to bridge to Render
const BRIDGE_KEYS = [
  "IVX_TWILIO_ACCOUNT_SID",
  "IVX_TWILIO_AUTH_TOKEN",
  "IVX_TWILIO_MESSAGING_SERVICE_SID",
  "IVX_TWILIO_FROM_PHONE",
  "EXPO_PUBLIC_SUPABASE_URL",
  "SUPABASE_URL",
  "IVX_SUPABASE_URL",
  "SUPABASE_SERVICE_ROLE_KEY",
  "SUPABASE_SERVICE_KEY",
  "EXPO_PUBLIC_SUPABASE_ANON_KEY",
  "SUPABASE_ANON_KEY",
  "SUPABASE_DB_URL",
  "DATABASE_URL",
  "AI_GATEWAY_API_KEY",
  "IVX_AI_GATEWAY_KEY",
  "JWT_SECRET",
  "APP_SECRET",
  "AWS_ACCESS_KEY_ID",
  "AWS_SECRET_ACCESS_KEY",
  "AWS_REGION",
  "CLOUDFRONT_DISTRIBUTION_ID",
  "IVX_AI_SYSTEM_SECRET",
  "IVX_INTERNAL_DEPLOY_SECRET",
  "IVX_INTERNAL_WORKER_ID",
  "IVX_OWNER_VARIABLES_ENCRYPTION_KEY",
  "IVX_OWNER_REGISTRATION_EMAILS",
  "IVX_OWNER_TOKEN",
  "IVX_OWNER_EMAIL",
  "IVX_SES_FROM_EMAIL",
  "IVX_OWNER_RECOVERY_PHONE",
];

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url);

    if (url.pathname === "/ping") {
      return Response.json({ ok: true, now: new Date().toISOString() });
    }

    // ── Debug: inspect all bridged env vars ──
    if (url.pathname === "/env-debug") {
      const debug: Record<string, any> = {};
      for (const key of BRIDGE_KEYS) {
        const val = env[key];
        if (val) {
          debug[key] = {
            masked: mask(val),
            length: val.length,
            hasWhitespace: val !== val.trim(),
          };
        }
      }
      // Also check for any other env vars that look important
      const allEnvKeys = Object.keys(env as Record<string, string>);
      const extraKeys = allEnvKeys.filter(k =>
        !BRIDGE_KEYS.includes(k) &&
        !k.startsWith("EXPO_PUBLIC_") &&
        !k.startsWith("RORK_") &&
        k.length > 3
      );
      debug._extra = extraKeys.map(k => ({ key: k, masked: mask(env[k]) }));
      return Response.json({ ok: true, debug });
    }

    // ── Return all bridged env var values (for Render push) ──
    if (url.pathname === "/all-raw") {
      const result: Record<string, string> = {};
      for (const key of BRIDGE_KEYS) {
        const val = env[key];
        if (val && val.trim()) {
          result[key] = val.trim();
        }
      }
      return Response.json(result);
    }

    // ── Send SMS directly via Twilio ──
    if (url.pathname === "/send-sms") {
      const accountSid = env.IVX_TWILIO_ACCOUNT_SID?.trim();
      const authToken = env.IVX_TWILIO_AUTH_TOKEN?.trim();
      const messagingServiceSid = env.IVX_TWILIO_MESSAGING_SERVICE_SID?.trim();
      const fromPhone = env.IVX_TWILIO_FROM_PHONE?.trim();

      if (!accountSid || !authToken || (!messagingServiceSid && !fromPhone)) {
        return Response.json({
          ok: false,
          error: "Missing Twilio credentials",
          debug: {
            accountSid: mask(accountSid),
            authToken: authToken ? `SET (len=${authToken.length})` : "NOT_SET",
            messagingServiceSid: mask(messagingServiceSid),
            fromPhone: fromPhone || "NOT_SET",
          },
        }, { status: 400 });
      }

      const toPhone = url.searchParams.get("to") || OWNER_PHONE;
      const customBody = url.searchParams.get("body");
      const messageBody = customBody ||
        "IVX AI Verification: Your autonomous work report SMS system is now LIVE. " +
        "Twilio integration confirmed operational. " +
        `Timestamp: ${new Date().toISOString()}`;

      const twilioUrl = `https://api.twilio.com/2010-04-01/Accounts/${accountSid}/Messages.json`;
      const authHeader = "Basic " + btoa(`${accountSid}:${authToken}`);

      const params = new URLSearchParams();
      params.append("To", toPhone);
      if (messagingServiceSid) {
        params.append("MessagingServiceSid", messagingServiceSid);
      } else {
        params.append("From", fromPhone!);
      }
      params.append("Body", messageBody);

      const res = await fetch(twilioUrl, {
        method: "POST",
        headers: {
          Authorization: authHeader,
          "Content-Type": "application/x-www-form-urlencoded",
        },
        body: params.toString(),
      });

      const responseText = await res.text();

      if (res.ok) {
        const data = JSON.parse(responseText);
        return Response.json({
          ok: true,
          messageSid: data.sid,
          status: data.status,
          to: data.to,
          from: data.from || messagingServiceSid,
          body: messageBody,
          timestamp: new Date().toISOString(),
        });
      }

      return Response.json({
        ok: false,
        error: `Twilio API returned ${res.status}`,
        detail: responseText.slice(0, 500),
        debug: {
          accountSidUsed: mask(accountSid),
          tokenLength: authToken.length,
        },
      }, { status: res.status });
    }

    // ── Full pipeline: bridge all envs to Render + trigger deploy + send SMS ──
    if (url.pathname === "/bridge-all") {
      const renderApiKey = request.headers.get("X-Render-Key") ||
        env.RENDER_API_KEY || "";
      const serviceId = env.RENDER_SERVICE_ID || "srv-d7t9ivreo5us73ftose0";

      const steps: Array<{ step: string; status: string; detail: string }> = [];

      // Step 1: Collect all env vars from Worker runtime
      const bridgedEnvs: Record<string, string> = {};
      for (const key of BRIDGE_KEYS) {
        const val = env[key]?.trim();
        if (val) {
          bridgedEnvs[key] = val;
        }
      }
      steps.push({
        step: "1_collect_envs",
        status: "PASS",
        detail: `${Object.keys(bridgedEnvs).length} env vars collected from Worker runtime`,
      });

      // Step 2: Get existing Render env vars
      const getRes = await fetch(
        `https://api.render.com/v1/services/${serviceId}/env-vars`,
        { headers: { Authorization: `Bearer ${renderApiKey}`, Accept: "application/json" } }
      );
      if (!getRes.ok) {
        const errText = await getRes.text();
        steps.push({
          step: "2_get_render_envs",
          status: "FAIL",
          detail: `Render GET failed: ${getRes.status} ${errText.slice(0, 100)}`,
        });
        return Response.json({ ok: false, steps }, { status: 500 });
      }

      const existingData = await getRes.json() as Array<{
        envVar: { key: string; value: string };
      }>;
      steps.push({
        step: "2_get_render_envs",
        status: "PASS",
        detail: `${existingData.length} existing Render env vars`,
      });

      // Step 3: Merge — keep existing, update/add bridged vars
      const allVars: Array<{ key: string; value: string }> = [];
      const existingKeys = new Set(existingData.map(d => d.envVar.key));

      // Keep existing vars that aren't being updated
      for (const item of existingData) {
        if (bridgedEnvs[item.envVar.key] !== undefined) {
          // Update with bridged value
          allVars.push({ key: item.envVar.key, value: bridgedEnvs[item.envVar.key] });
        } else {
          // Keep existing value
          allVars.push({ key: item.envVar.key, value: item.envVar.value });
        }
      }

      // Add new bridged vars that don't exist on Render yet
      let addedCount = 0;
      for (const [key, value] of Object.entries(bridgedEnvs)) {
        if (!existingKeys.has(key)) {
          allVars.push({ key, value });
          addedCount++;
        }
      }

      steps.push({
        step: "3_merge_envs",
        status: "PASS",
        detail: `${allVars.length} total vars (${addedCount} new, ${existingData.length} existing)`,
      });

      // Step 4: PUT to Render
      const putRes = await fetch(
        `https://api.render.com/v1/services/${serviceId}/env-vars`,
        {
          method: "PUT",
          headers: {
            Authorization: `Bearer ${renderApiKey}`,
            "Content-Type": "application/json",
            Accept: "application/json",
          },
          body: JSON.stringify(allVars),
        }
      );

      if (!putRes.ok) {
        const errText = await putRes.text();
        steps.push({
          step: "4_put_render_envs",
          status: "FAIL",
          detail: `PUT failed: ${putRes.status} ${errText.slice(0, 200)}`,
        });
        return Response.json({ ok: false, steps }, { status: 500 });
      }

      steps.push({
        step: "4_put_render_envs",
        status: "PASS",
        detail: `${allVars.length} env vars pushed to Render`,
      });

      // Step 5: Trigger deploy
      const deployRes = await fetch(
        `https://api.render.com/v1/services/${serviceId}/deploys`,
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${renderApiKey}`,
            "Content-Type": "application/json",
            Accept: "application/json",
          },
          body: JSON.stringify({ clearCache: "do_not_clear" }),
        }
      );

      const deployData = await deployRes.json();
      steps.push({
        step: "5_trigger_deploy",
        status: deployData.id ? "PASS" : "FAIL",
        detail: deployData.id ? `Deploy: ${deployData.id}` : `Failed: ${JSON.stringify(deployData).slice(0, 100)}`,
      });

      // Step 6: Send SMS directly (don't wait for deploy)
      const accountSid = env.IVX_TWILIO_ACCOUNT_SID?.trim();
      const authToken = env.IVX_TWILIO_AUTH_TOKEN?.trim();
      const messagingServiceSid = env.IVX_TWILIO_MESSAGING_SERVICE_SID?.trim();
      const fromPhone = env.IVX_TWILIO_FROM_PHONE?.trim();

      if (accountSid && authToken && (messagingServiceSid || fromPhone)) {
        const twilioUrl = `https://api.twilio.com/2010-04-01/Accounts/${accountSid}/Messages.json`;
        const authHeader = "Basic " + btoa(`${accountSid}:${authToken}`);
        const params = new URLSearchParams();
        params.append("To", OWNER_PHONE);
        if (messagingServiceSid) {
          params.append("MessagingServiceSid", messagingServiceSid);
        } else {
          params.append("From", fromPhone!);
        }
        params.append("Body",
          "IVX AI Verification: Your autonomous work report SMS system is now LIVE. " +
          "Twilio integration confirmed operational. " +
          `Timestamp: ${new Date().toISOString()}`
        );

        const smsRes = await fetch(twilioUrl, {
          method: "POST",
          headers: {
            Authorization: authHeader,
            "Content-Type": "application/x-www-form-urlencoded",
          },
          body: params.toString(),
        });

        const smsText = await smsRes.text();

        if (smsRes.ok) {
          const smsData = JSON.parse(smsText);
          steps.push({
            step: "6_send_sms",
            status: "PASS",
            detail: `Message SID: ${smsData.sid}, Status: ${smsData.status}`,
          });
          return Response.json({
            ok: true,
            steps,
            deployId: deployData.id,
            sms: {
              messageSid: smsData.sid,
              status: smsData.status,
              to: smsData.to,
            },
          });
        } else {
          let errMsg = smsText.slice(0, 200);
          try {
            const errData = JSON.parse(smsText);
            errMsg = `${errData.code}: ${errData.message}`;
          } catch {}
          steps.push({
            step: "6_send_sms",
            status: "FAIL",
            detail: `Twilio ${smsRes.status}: ${errMsg}`,
          });
        }
      } else {
        steps.push({
          step: "6_send_sms",
          status: "SKIP",
          detail: "Twilio credentials incomplete",
        });
      }

      return Response.json({
        ok: false,
        steps,
        deployId: deployData.id,
        smsError: "SMS send failed or skipped — see steps",
      }, { status: 500 });
    }

    return Response.json({ ok: true, hello: "world" });
  },
};

