const accountSid = bridged.IVX_TWILIO_ACCOUNT_SID;
const authToken = bridged.IVX_TWILIO_AUTH_TOKEN;
const mgSid = bridged.IVX_TWILIO_MESSAGING_SERVICE_SID;
const fromPhone = bridged.IVX_TWILIO_FROM_PHONE;

