/**
 * IVX Credential Bridge — Final (clean)
 * Tests AI gateway + Twilio from the Rork platform's private env store.
 */

interface Env {
  IVX_TWILIO_ACCOUNT_SID?: string;
  IVX_TWILIO_AUTH_TOKEN?: string;
  IVX_TWILIO_MESSAGING_SERVICE_SID?: string;
  IVX_TWILIO_FROM_PHONE?: string;
  AI_GATEWAY_API_KEY?: string;
  IVX_AI_GATEWAY_KEY?: string;
  [key: string]: string | undefined;
}

const OWNER_PHONE = "+15616443503";

function mask(val: string | undefined): string {
  if (!val) return "NOT_SET";
  if (val.length <= 8) return "***";
  return val.slice(0, 4) + "..." + val.slice(-4);
}

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url);

    if (url.pathname === "/ping") {
      return Response.json({ ok: true, now: new Date().toISOString() });
    }

    // ── Test AI Gateway (Vercel) ──
    if (url.pathname === "/test-gateway") {
      const gatewayKey = env.IVX_AI_GATEWAY_KEY?.trim() || env.AI_GATEWAY_API_KEY?.trim();
      if (!gatewayKey) {
        return Response.json({ ok: false, error: "No AI gateway key found" }, { status: 400 });
      }

      const maskedKey = mask(gatewayKey);
      const keyPrefix = gatewayKey.slice(0, 6);

      // Try a minimal chat completion via Vercel AI Gateway
      const gatewayUrl = "https://ai-gateway.vercel.sh/v1/chat/completions";
      const res = await fetch(gatewayUrl, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${gatewayKey}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          model: "openai/gpt-4o",
          messages: [{ role: "user", content: "Say 'working' in one word." }],
          max_tokens: 10,
        }),
      });

      const responseText = await res.text();

      return Response.json({
        ok: res.ok,
        httpStatus: res.status,
        keyMasked: maskedKey,
        keyPrefix: keyPrefix,
        keyLength: gatewayKey.length,
        gatewayUrl,
        response: responseText.slice(0, 500),
        testedAt: new Date().toISOString(),
      });
    }

    // ── Test Twilio auth ──
    if (url.pathname === "/test-twilio") {
      const accountSid = env.IVX_TWILIO_ACCOUNT_SID?.trim();
      const authToken = env.IVX_TWILIO_AUTH_TOKEN?.trim();

      if (!accountSid || !authToken) {
        return Response.json({ ok: false, error: "Missing Twilio creds" }, { status: 400 });
      }

      // Try fetching the account to verify auth
      const authHeader = "Basic " + btoa(`${accountSid}:${authToken}`);
      const res = await fetch(
        `https://api.twilio.com/2010-04-01/Accounts/${accountSid}.json`,
        { headers: { Authorization: authHeader } }
      );

      const responseText = await res.text();
      let accountInfo: any = null;
      if (res.ok) {
        accountInfo = JSON.parse(responseText);
      }

      return Response.json({
        ok: res.ok,
        httpStatus: res.status,
        accountSidMasked: mask(accountSid),
        authTokenLength: authToken.length,
        authTokenIsHex: /^[0-9a-fA-F]+$/.test(authToken),
        accountStatus: accountInfo?.status || null,
        accountFriendlyName: accountInfo?.friendly_name || null,
        error: res.ok ? null : responseText.slice(0, 300),
        testedAt: new Date().toISOString(),
      });
    }

    // ── Send SMS via Twilio ──
    if (url.pathname === "/send-sms") {
      const accountSid = env.IVX_TWILIO_ACCOUNT_SID?.trim();
      const authToken = env.IVX_TWILIO_AUTH_TOKEN?.trim();
      const messagingServiceSid = env.IVX_TWILIO_MESSAGING_SERVICE_SID?.trim();
      const fromPhone = env.IVX_TWILIO_FROM_PHONE?.trim();

      if (!accountSid || !authToken || (!messagingServiceSid && !fromPhone)) {
        return Response.json({ ok: false, error: "Missing Twilio creds" }, { status: 400 });
      }

      const toPhone = url.searchParams.get("to") || OWNER_PHONE;
      const messageBody = url.searchParams.get("body") ||
        "IVX AI Verification: Autonomous work report SMS system is LIVE. " +
        `Twilio integration confirmed. ${new Date().toISOString()}`;

      const twilioUrl = `https://api.twilio.com/2010-04-01/Accounts/${accountSid}/Messages.json`;
      const authHeader = "Basic " + btoa(`${accountSid}:${authToken}`);
      const params = new URLSearchParams();
      params.append("To", toPhone);
      if (messagingServiceSid) {
        params.append("MessagingServiceSid", messagingServiceSid);
      } else {
        params.append("From", fromPhone!);
      }
      params.append("Body", messageBody);

      const res = await fetch(twilioUrl, {
        method: "POST",
        headers: {
          Authorization: authHeader,
          "Content-Type": "application/x-www-form-urlencoded",
        },
        body: params.toString(),
      });

      const responseText = await res.text();

      if (res.ok) {
        const data = JSON.parse(responseText);
        return Response.json({
          ok: true,
          messageSid: data.sid,
          status: data.status,
          to: data.to,
          from: data.from || messagingServiceSid,
          body: messageBody,
          timestamp: new Date().toISOString(),
        });
      }

      return Response.json({
        ok: false,
        httpStatus: res.status,
        error: responseText.slice(0, 500),
      }, { status: res.status });
    }

    return Response.json({ ok: true, hello: "world" });
  },
};

